window.CACHASTE_HISTORIA.push(...[["Historia de Chile","¿Qué proceso impulsó el desarrollo de ciudades mineras en el norte de Chile durante el siglo XIX?",["La explotación de recursos minerales para exportación","El abandono de la actividad extractiva","La desaparición de rutas ferroviarias","El cierre de los puertos comerciales"],0,"La minería del cobre, plata y salitre impulsó asentamientos y circuitos comerciales en el norte.","Relaciona actividad económica y población."],["Historia de Chile","¿Qué se entiende por cuestión social en Chile a fines del siglo XIX y comienzos del XX?",["Conjunto de problemas laborales y de vivienda asociados a la urbanización","Una disputa exclusiva por límites internacionales","Un programa de expansión territorial colonial","La desaparición del trabajo asalariado"],0,"La cuestión social agrupó precariedad laboral, hacinamiento y demandas por protección social.","Piensa en las condiciones de vida de trabajadores urbanos."],["Historia de Chile","¿Cuál fue una consecuencia política de la Guerra Civil chilena de 1891?",["El fortalecimiento del predominio parlamentario sobre el Ejecutivo","La instauración inmediata del sufragio universal","La abolición del Congreso Nacional","La independencia respecto de España"],0,"Tras la derrota de Balmaceda se consolidó un sistema de predominio parlamentario en la práctica política.","Observa la relación entre Congreso y presidencia."],["Historia de Chile","¿Qué propósito tuvo la CORFO, creada en 1939?",["Promover el desarrollo productivo y la industrialización","Organizar elecciones presidenciales","Reemplazar a los tribunales de justicia","Regular exclusivamente la educación primaria"],0,"La CORFO impulsó proyectos productivos y políticas de industrialización en Chile.","Relaciona la institución con el desarrollo económico."],["Historia de Chile","¿Qué cambio caracterizó la reforma agraria chilena de la segunda mitad del siglo XX?",["Redistribución de tierras y transformación de la propiedad agrícola","Eliminación de toda actividad campesina","Privatización obligatoria de las playas","Prohibición de sindicatos urbanos"],0,"La reforma agraria buscó modificar la estructura de tenencia de la tierra y las relaciones productivas rurales.","Piensa en quién posee y trabaja la tierra."],["Historia de Chile","¿Qué resultado tuvo el plebiscito chileno de 1988?",["Ganó la opción No a la continuidad de Augusto Pinochet","Se aprobó la Constitución de 1833","Se eligió al primer presidente de Chile","Se declaró la independencia nacional"],0,"La victoria del No abrió el camino a elecciones presidenciales y a la transición democrática.","Ubica el plebiscito en la transición de los años ochenta."],["Historia de Chile","¿Qué es una fuente primaria para estudiar una época histórica?",["Un documento producido en el período estudiado","Una novela histórica escrita siglos después","Un manual escolar contemporáneo","Un resumen elaborado por un investigador actual"],0,"Una fuente primaria proviene del período o de protagonistas del hecho, como una carta de la época.","Identifica cuándo y por quién se produjo el testimonio."],["Historia de Chile","¿Qué indica que una interpretación histórica puede cambiar?",["Que nuevas fuentes y preguntas permiten revisar explicaciones","Que todos los hechos pasados desaparecen","Que ninguna evidencia es necesaria","Que las fechas dejan de importar"],0,"La investigación histórica contrasta evidencias y puede reformular interpretaciones con nuevas fuentes.","Distingue hechos documentados de interpretaciones."],["Historia mundial","¿Qué factor contribuyó al crecimiento de ciudades durante la Revolución Industrial?",["Concentración de fábricas y empleo asalariado","Prohibición universal de migraciones","Desaparición de actividades manufactureras","Retorno masivo obligatorio al campo"],0,"La industria fabril atrajo trabajadores a centros urbanos y aceleró procesos de urbanización.","Relaciona lugar de trabajo y movilidad de población."],["Historia mundial","¿Qué fue la Guerra Fría?",["Rivalidad geopolítica e ideológica entre bloques liderados por EE. UU. y la URSS","Una guerra exclusivamente medieval","Un conflicto entre Chile y Perú en 1810","Una campaña para eliminar el comercio internacional"],0,"La Guerra Fría articuló competencia política, tecnológica y militar entre dos grandes bloques sin guerra directa generalizada entre sus potencias.","Piensa en el orden mundial posterior a 1945."],["Historia mundial","¿Qué principio difundió la Declaración de los Derechos del Hombre y del Ciudadano de 1789?",["Igualdad jurídica y derechos fundamentales","Privilegios legales hereditarios para todos los estamentos","Eliminación de la ciudadanía","Restablecimiento universal de la servidumbre"],0,"El documento revolucionario francés afirmó derechos y principios de igualdad ante la ley.","Relaciona la declaración con la Revolución francesa."],["Historia mundial","¿Qué consecuencia tuvo la expansión imperialista europea del siglo XIX en África?",["Dominación colonial y reorganización de territorios","Independencia inmediata de todos los territorios","Fin absoluto de la explotación de recursos","Ausencia de resistencias locales"],0,"El imperialismo impuso administraciones coloniales y fronteras con profundos efectos políticos y económicos.","Identifica las relaciones de poder entre colonizadores y colonizados."],["Historia mundial","¿Qué proceso impulsó la descolonización después de 1945?",["Movimientos de independencia en Asia y África","Restauración completa de imperios europeos","Desaparición de organizaciones nacionalistas","Fin de la autodeterminación de los pueblos"],0,"Tras la Segunda Guerra Mundial crecieron movimientos nacionalistas y procesos de independencia en territorios coloniales.","Ubica el cambio en el escenario internacional de posguerra."],["Formación ciudadana","¿Qué significa que una Constitución limite el ejercicio del poder?",["Que las autoridades deben respetar competencias y derechos","Que cualquier autoridad puede ignorar la ley","Que desaparecen los controles institucionales","Que las elecciones no tienen efectos"],0,"El constitucionalismo establece reglas, atribuciones y límites al ejercicio del poder estatal.","Relaciona límites con prevención de abusos."],["Formación ciudadana","¿Qué función cumple el principio de separación de poderes?",["Distribuir funciones y establecer controles recíprocos","Concentrar todas las decisiones en un solo órgano","Impedir la existencia de tribunales","Eliminar la elaboración de leyes"],0,"La separación de poderes busca evitar concentración de autoridad y favorecer mecanismos de control.","Identifica quién legisla, ejecuta y juzga."],["Formación ciudadana","¿Qué es la participación ciudadana más allá del voto?",["Intervenir en asuntos públicos mediante organizaciones y deliberación","Delegar toda decisión sin informarse","Prohibir la asociación comunitaria","Restringir la discusión a autoridades electas"],0,"La ciudadanía también participa mediante organizaciones, debates, consultas y control social.","Piensa en acciones colectivas fuera de las elecciones."],["Formación ciudadana","¿Cuál es un ejemplo de discriminación arbitraria?",["Negar un servicio por un prejuicio sin justificación razonable","Aplicar el mismo horario de atención a todos","Exigir requisitos técnicos pertinentes al cargo","Ofrecer información accesible a personas con discapacidad"],0,"La discriminación arbitraria establece distinciones sin justificación razonable que afectan el ejercicio de derechos.","Distingue criterios pertinentes de prejuicios."],["Formación ciudadana","¿Qué aporta la libertad de prensa a una democracia?",["Facilita información y fiscalización del poder","Garantiza que toda noticia sea verdadera","Elimina la necesidad de contrastar fuentes","Sustituye automáticamente a los tribunales"],0,"Una prensa libre contribuye al debate y control público, aunque requiere verificación y responsabilidad.","Relaciona acceso a información y rendición de cuentas."],["Formación ciudadana","¿Qué implica el debido proceso?",["Garantías para ser oído y juzgado conforme a procedimientos legales","Condena sin defensa ni tribunal","Decisiones secretas sin posibilidad de revisión","Ausencia de reglas para investigar"],0,"El debido proceso protege garantías como defensa, imparcialidad y procedimientos establecidos por la ley.","Piensa en derechos de quienes enfrentan un procedimiento."],["Economía y sociedad","¿Qué representa el producto interno bruto de un país?",["El valor de bienes y servicios finales producidos en un período","La riqueza acumulada de una sola empresa","La cantidad de billetes impresos","El total de habitantes de una ciudad"],0,"El PIB mide el valor de la producción final realizada dentro de una economía durante un período.","Distingue producción anual de riqueza acumulada."],["Economía y sociedad","¿Qué caracteriza al desempleo en estadísticas laborales?",["Personas sin trabajo que buscan empleo y están disponibles","Todas las personas que no reciben sueldo","Exclusivamente quienes estudian","Todas las personas jubiladas"],0,"El desempleo considera criterios de falta de ocupación, búsqueda y disponibilidad según las mediciones laborales.","No toda persona sin empleo pertenece a la fuerza laboral."],["Economía y sociedad","¿Qué ocurre si aumenta la oferta de un producto y la demanda se mantiene constante, en un mercado competitivo?",["El precio de equilibrio tiende a disminuir","El precio necesariamente se duplica","La demanda desaparece","La cantidad ofrecida siempre cae a cero"],0,"Un desplazamiento de la oferta hacia la derecha suele reducir el precio de equilibrio y elevar la cantidad transada.","Imagina más unidades disponibles al mismo nivel de demanda."],["Economía y sociedad","¿Qué es un impuesto progresivo?",["Uno cuya tasa efectiva aumenta al crecer la base gravada","Uno que cobra igual monto fijo a toda persona","Uno que disminuye necesariamente con los ingresos","Uno que solo se aplica a productos importados"],0,"Un impuesto progresivo aumenta la carga relativa a medida que crece la capacidad contributiva medida por su base.","Observa cómo cambia la tasa relativa al aumentar la base."],["Economía y sociedad","¿Cuál es una consecuencia posible de una externalidad negativa?",["Costos para terceros no incorporados plenamente en el precio","Beneficios privados sin efecto social","Desaparición automática de contaminación","Aumento obligatorio del bienestar colectivo"],0,"Una externalidad negativa impone costos a terceros, como contaminación que afecta a vecinos.","Busca efectos sobre personas ajenas a la transacción."],["Economía y sociedad","¿Qué significa diversificar una inversión?",["Distribuir recursos entre distintos activos para reducir exposición específica","Poner todos los ahorros en un solo activo","Garantizar ganancias sin riesgo","Eliminar cualquier fluctuación económica"],0,"La diversificación puede reducir riesgos específicos, aunque no elimina todos los riesgos de mercado.","Evita concentrar todos los recursos en un solo lugar."],["Interpretación de fuentes","Una carta de 1900 describe jornadas laborales extensas. ¿Qué se puede inferir con mayor prudencia?",["Que el autor percibía condiciones laborales exigentes en su entorno","Que todos los trabajadores del mundo vivían igual","Que no existían leyes en ningún país","Que la carta demuestra por sí sola cifras nacionales exactas"],0,"La fuente testimonia una experiencia situada; generalizar requiere contrastar otros documentos y datos.","Distingue testimonio particular de conclusión general."],["Interpretación de fuentes","Un gráfico muestra aumento sostenido de matrícula escolar entre 1950 y 1970. ¿Qué conclusión respalda?",["La matrícula creció en el período mostrado","La calidad educativa aumentó exactamente en la misma proporción","Todos los estudiantes finalizaron sus estudios","No hubo diferencias territoriales"],0,"El gráfico respalda una tendencia cuantitativa de matrícula, pero no demuestra por sí mismo calidad ni cobertura homogénea.","No infieras variables que el gráfico no mide."],["Interpretación de fuentes","Dos periódicos describen de modo distinto una misma protesta. ¿Qué estrategia de análisis es más apropiada?",["Comparar perspectivas, evidencias y contexto editorial","Elegir automáticamente el texto más extenso","Descartar todas las fuentes sin leerlas","Asumir que ambas versiones son idénticas"],0,"Contrastar fuentes permite reconocer enfoques y sesgos sin renunciar a la verificación factual.","Observa quién escribe, para quién y con qué pruebas."],["Interpretación de fuentes","Un mapa histórico muestra cambios fronterizos. ¿Qué otra evidencia ayudaría a explicar sus causas?",["Tratados, conflictos y decisiones políticas de la época","Solo la escala gráfica del mapa","Únicamente el color de los países","La cantidad de letras en la leyenda"],0,"Para explicar transformaciones territoriales se deben contrastar mapas con documentos políticos y procesos históricos.","Un mapa muestra cambios, pero no siempre sus causas."]] .map(([area,question,options,answer,why,hint],i)=>({id:'HIS-'+String(i+21).padStart(3,'0'),area,question,options,answer,why,hint,origin:'original'})));

window.CACHASTE_HISTORIA.push({id:'HIS-050',area:'Interpretación de fuentes',question:'Un censo registra un aumento de población urbana de 40% a 60% en veinte años. ¿Qué indica ese dato?',options:['Que creció la proporción de habitantes urbanos','Que todas las ciudades duplicaron habitantes','Que la población rural desapareció','Que aumentó exactamente 20% la población total'],answer:0,why:'Los porcentajes describen la participación relativa de la población urbana, no la variación absoluta del total.',hint:'Distingue proporción de cantidad total.',origin:'original'});

window.CACHASTE_HISTORIA.push(...[["Historia de Chile","¿Qué efecto tuvo la llegada del ferrocarril a diversas regiones chilenas en el siglo XIX?",["Facilitó el transporte y la articulación de mercados","Eliminó de inmediato el comercio marítimo","Impidió toda migración interna","Suprimió la producción agrícola"],0,"El ferrocarril mejoró la conexión entre centros productivos, ciudades y puertos.","Relaciona infraestructura con circulación de bienes."],["Historia mundial","¿Qué hecho suele marcar el inicio de la Primera Guerra Mundial en 1914?",["El asesinato del archiduque Francisco Fernando","La caída del muro de Berlín","La fundación de la ONU","La crisis económica de 1929"],0,"El atentado de Sarajevo desencadenó una crisis diplomática y militar entre potencias europeas.","Distingue detonante inmediato y causas estructurales."],["Formación ciudadana","¿Qué finalidad tiene la rendición de cuentas de una autoridad pública?",["Permitir evaluar y controlar el ejercicio de sus funciones","Eliminar la transparencia administrativa","Impedir la participación ciudadana","Reemplazar todas las elecciones"],0,"La rendición de cuentas permite conocer decisiones, uso de recursos y responsabilidades públicas.","Relaciona información pública y control democrático."],["Economía y sociedad","Si una persona ahorra $10.000 mensuales durante seis meses sin intereses, ¿cuánto acumula?",["$60.000","$16.000","$50.000","$100.000"],0,"El ahorro acumulado es 10.000 multiplicado por seis meses: 60.000 pesos.","Multiplica aporte periódico por número de períodos."],["Interpretación de fuentes","Un registro electoral muestra que votó el 70% del padrón. ¿Qué conclusión se justifica?",["Participaron siete de cada diez personas habilitadas","Votó el 70% de toda la población del país","Todos los votantes eligieron la misma opción","El padrón creció exactamente un 70%"],0,"La participación se calcula sobre personas inscritas o habilitadas, no necesariamente sobre toda la población.","Identifica cuál es el denominador del porcentaje."],["Historia de Chile","¿Qué fue la ocupación de la Araucanía en el siglo XIX?",["Un proceso de incorporación territorial estatal que afectó profundamente al pueblo mapuche","Una expedición científica sin intervención militar","La fundación de la ONU en el sur de Chile","Un tratado de independencia firmado en 1810"],0,"El avance militar y administrativo del Estado chileno transformó el territorio y las condiciones de vida mapuche.","Considera sus dimensiones territoriales y sociales."],["Historia mundial","¿Qué buscaba el Plan Marshall después de la Segunda Guerra Mundial?",["Apoyar la reconstrucción económica de Europa occidental","Organizar la conquista española de América","Financiar la Primera Guerra Mundial","Abolir todos los bancos centrales"],0,"El programa estadounidense entregó apoyo para la recuperación económica europea de posguerra.","Ubica la iniciativa en el contexto de 1947."],["Formación ciudadana","¿Qué significa soberanía popular en una democracia?",["Que la legitimidad del poder político se funda en el pueblo","Que los cargos son necesariamente hereditarios","Que no existen derechos fundamentales","Que los tribunales dictan todas las leyes"],0,"La soberanía popular sitúa en la ciudadanía el fundamento de la autoridad política.","Distingue poder popular de privilegio hereditario."],["Economía y sociedad","Una municipalidad dispone de presupuesto para construir una biblioteca o mejorar una plaza, pero no ambas. Decide construir la biblioteca. ¿Qué representa su costo de oportunidad?",["El beneficio de mejorar la plaza al que se renunció","El gasto total de construir ambas obras","Una multa por no mejorar la plaza","El presupuesto que quedará necesariamente sin utilizar"],0,"El costo de oportunidad de elegir la biblioteca es el beneficio de la mejor alternativa descartada: mejorar la plaza. No equivale al costo monetario de todas las opciones.","Identifica la alternativa que no se eligió y el beneficio que habría aportado."],["Interpretación de fuentes","Una fotografía muestra una protesta, pero no incluye fecha ni lugar. ¿Qué conviene hacer antes de interpretarla?",["Investigar procedencia, contexto y autenticidad","Suponer que representa a todo el país","Atribuirle una fecha arbitraria","Descartar cualquier otra evidencia"],0,"La contextualización evita interpretaciones erróneas y ayuda a verificar qué representa realmente la imagen.","Comprueba cuándo, dónde y quién registró la escena."],["Historia de Chile","¿Qué significó la nacionalización del cobre en Chile en 1971?",["La transferencia al Estado de la gran minería del cobre mediante reforma constitucional","La eliminación completa de toda actividad minera","La creación del Banco Central","La independencia política de Chile"],0,"La reforma constitucional de 1971 permitió nacionalizar empresas de la gran minería del cobre.","Relaciona el proceso con la propiedad de recursos estratégicos."],["Historia mundial","¿Qué fue la Gran Depresión iniciada en 1929?",["Una crisis económica internacional de gran magnitud","Una recesión limitada exclusivamente a Estados Unidos","Una crisis causada únicamente por la Segunda Guerra Mundial","Una etapa de crecimiento sostenido del empleo y el comercio mundial"],0,"La crisis iniciada en 1929 produjo contracción económica, desempleo y efectos internacionales.","Distingue crisis económica de guerra o institución."],["Formación ciudadana","¿Qué función cumplen las elecciones periódicas en una democracia representativa?",["Permiten renovar autoridades y exigir responsabilidad política","Permiten renovar autoridades, pero eliminan el control entre elecciones","Sustituyen los mecanismos de fiscalización institucional por el voto","Garantizan por sí solas que todas las decisiones públicas sean legítimas"],0,"Las elecciones periódicas permiten a la ciudadanía elegir representantes y evaluar su gestión.","Relaciona representación con alternancia y control."],["Economía y sociedad","¿Qué suele ocurrir con la demanda de un bien normal cuando aumenta el ingreso, manteniendo lo demás constante?",["Tiende a aumentar","Tiende a disminuir, como ocurre con un bien inferior","Permanece necesariamente constante aunque cambie el ingreso","Aumenta solo si el precio del bien también sube"],0,"Por definición, la cantidad demandada de un bien normal tiende a aumentar cuando sube el ingreso.","Recuerda la relación entre ingreso y bien normal."],["Interpretación de fuentes","Un gráfico presenta solo valores absolutos de desempleados. ¿Qué dato adicional permite comparar tasas entre países?",["El tamaño de sus fuerzas laborales","La población total sin distinguir participación laboral","El número de personas ocupadas sin conocer la fuerza laboral","El producto interno bruto de cada país"],0,"Para comparar tasas de desempleo se necesita el número de personas desempleadas relativo a la fuerza laboral.","Distingue cantidad absoluta de tasa relativa."]].map(([area,question,options,answer,why,hint],i)=>({id:'HIS-'+String(i+51).padStart(3,'0'),area,question,options,answer,why,hint,origin:'original'})));

